/**
 * ==========================================================================
 * DESIGN SYSTEM ORÇAMENTO — RUNTIME ENGINE DE APRESENTAÇÕES INSTITUCIONAIS
 * Governo do Estado de Goiás — Secretaria da Economia
 * Arquivo: deck.js (Imutável / Produção)
 * Versão: 2.2 — Exportação Layered PPTX (Camadas Nativas) & PDF Taint-Free
 * ==========================================================================
 */

(function () {
  'use strict';

  // ATIVOS OFICIAIS EMBUTIDOS EM BASE64
  // Elimina dependência de rede externa para fundos e previne canvas tainted (CORS) sob file:///
  const ASSETS = {
  bgConteudo: "data:image/png;base64,",
  encerramento: "data:image/png;base64,"
};

  // SVGs OFICIAIS PARA SUBSTITUIÇÃO AUTOMÁTICA DE EMOJIS (ANTI-HALLUCINATION)
  const SVG_ICONS = {
    chart: `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/></svg>`,
    balance: `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m16 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z"/><path d="m2 16 3-8 3 8c-.87.65-1.92 1-3 1s-2.13-.35-3-1Z"/><path d="M7 21h10"/><path d="M12 3v18"/><path d="M3 7h2c2 0 5-1 7-2 2 1 5 2 7 2h2"/></svg>`,
    shield: `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>`,
    pin: `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>`,
    alert: `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>`
  };

  let currentSlide = 1;
  let totalSlides = 1;
  let chartInstances = {};

  // Utilitário para converter cores CSS para formato Hexadecimal aceito pelo PptxGenJS (RRGGBB)
  function parseColorToHex(colorStr, defaultHex = 'FFFFFF') {
    if (!colorStr) return defaultHex;
    colorStr = colorStr.trim();
    if (colorStr.startsWith('#')) {
      let hex = colorStr.replace('#', '');
      if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
      return hex.toUpperCase().substring(0, 6);
    }
    const m = colorStr.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/i);
    if (m) {
      const r = parseInt(m[1], 10).toString(16).padStart(2, '0');
      const g = parseInt(m[2], 10).toString(16).padStart(2, '0');
      const b = parseInt(m[3], 10).toString(16).padStart(2, '0');
      return `${r}${g}${b}`.toUpperCase();
    }
    return defaultHex;
  }

  // Utilitário para converter cores CSS para tupla [R, G, B] aceita pelo jsPDF
  function parseColorToRgb(colorStr, defaultRgb = [255, 255, 255]) {
    if (!colorStr) return defaultRgb;
    colorStr = colorStr.trim();
    if (colorStr.startsWith('#')) {
      let hex = colorStr.replace('#', '');
      if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
      return [
        parseInt(hex.substring(0, 2), 16) || 0,
        parseInt(hex.substring(2, 4), 16) || 0,
        parseInt(hex.substring(4, 6), 16) || 0
      ];
    }
    const m = colorStr.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/i);
    if (m) {
      return [parseInt(m[1], 10), parseInt(m[2], 10), parseInt(m[3], 10)];
    }
    return defaultRgb;
  }

  // 1. SANITIZADOR AUTOMÁTICO DE EMOJIS (Transforma emojis informais em SVGs de Estado)
  function sanitizeEmojis() {
    const emojiMap = [
      { regex: /📈|📊/g, svg: SVG_ICONS.chart },
      { regex: /⚖️|⚖/g, svg: SVG_ICONS.balance },
      { regex: /🛡️|🛡/g, svg: SVG_ICONS.shield },
      { regex: /📌|📍|📝/g, svg: SVG_ICONS.pin },
      { regex: /⚠️|🚨|❗/g, svg: SVG_ICONS.alert }
    ];

    document.querySelectorAll('.card-soft-sage, .slide-title, .breadcrumb, h3, p').forEach(el => {
      let html = el.innerHTML;
      emojiMap.forEach(item => {
        if (item.regex.test(html)) {
          html = html.replace(item.regex, `<span class="icon-box-sage" style="display:inline-flex;margin-right:8px;vertical-align:middle;">${item.svg}</span>`);
        }
      });
      // Remove outros emojis residuais
      html = html.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}]/gu, '');
      el.innerHTML = html;
    });
  }

  // 2. AUTO-SCALE GPU 16:9
  function autoScale() {
    const stageW = window.innerWidth;
    const stageH = window.innerHeight;
    const scale = Math.min(stageW / 1920, stageH / 1080);
    document.documentElement.style.setProperty('--scale', scale);
  }

  // 3. AUTO-RENDERIZADOR DECLARATIVO DE GRÁFICOS CHART.JS
  function initCharts() {
    if (typeof Chart === 'undefined') return;

    // A. Gráficos Declarativos via data-attributes
    document.querySelectorAll('.deck-chart').forEach((el, index) => {
      const type = el.getAttribute('data-type') || 'bar';
      const canvasId = `auto-chart-${index + 1}`;
      el.innerHTML = `<div class="chart-container-box"><canvas id="${canvasId}"></canvas></div>`;
      const ctx = document.getElementById(canvasId);

      if (type === 'bar') {
        const labels = JSON.parse(el.getAttribute('data-labels') || '["Jan/Fev", "Mar/Abr", "Mai/Jun", "Jul/Ago", "Set/Out"]');
        const s1 = JSON.parse(el.getAttribute('data-series-1') || '{"label": "Receita Realizada", "data": [42, 58, 51, 74, 92]}');
        const s2 = JSON.parse(el.getAttribute('data-series-2') || '{"label": "Despesa Liquidada", "data": [35, 44, 46, 62, 70]}');

        chartInstances[canvasId] = new Chart(ctx, {
          type: 'bar',
          data: {
            labels: labels,
            datasets: [
              { label: s1.label, data: s1.data, backgroundColor: '#219647', borderRadius: 6, borderSkipped: false },
              { label: s2.label, data: s2.data, backgroundColor: '#738b7b', borderRadius: 6, borderSkipped: false }
            ]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: { position: 'top', labels: { color: '#0d1711', font: { family: 'Segoe UI', weight: '600', size: 13 }, usePointStyle: true, pointStyle: 'circle' } }
            },
            scales: {
              x: { grid: { display: false }, ticks: { color: '#4f6656', font: { family: 'Segoe UI', weight: '600' } } },
              y: { grid: { color: 'rgba(20, 48, 42, 0.08)' }, ticks: { color: '#4f6656', font: { family: 'Segoe UI' }, callback: v => `R$ ${v}M` } }
            }
          }
        });
      } else if (type === 'donut' || type === 'doughnut') {
        const labels = JSON.parse(el.getAttribute('data-labels') || '["Educação", "Saúde", "Infraestrutura", "Segurança", "Administração"]');
        const values = JSON.parse(el.getAttribute('data-values') || '[28.1, 22.4, 18.5, 16.8, 14.2]');

        chartInstances[canvasId] = new Chart(ctx, {
          type: 'doughnut',
          data: {
            labels: labels,
            datasets: [{
              data: values,
              backgroundColor: ['#219647', '#738b7b', '#9eb2a4', '#cbd8cf', '#dee8e1', '#eaf1ed'],
              borderRadius: 6,
              spacing: 3
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '62%',
            plugins: {
              legend: { position: 'right', labels: { color: '#0d1711', font: { family: 'Segoe UI', weight: '600', size: 12 }, usePointStyle: true, pointStyle: 'circle', padding: 14 } }
            }
          }
        });
      }
    });
  }

  // 4. ATUALIZADOR DE SLIDES & PLAYER
  function updateSlides() {
    const slides = document.querySelectorAll('.slide');
    totalSlides = slides.length || 1;

    slides.forEach((slide, idx) => {
      if (idx + 1 === currentSlide) {
        slide.classList.add('active');
      } else {
        slide.classList.remove('active');
      }
    });

    const indicator = document.getElementById('slideIndicator');
    if (indicator) indicator.innerText = `Slide ${currentSlide} / ${totalSlides}`;

    autoScale();

    // Redimensiona instâncias do Chart.js para manter proporção
    if (typeof Chart !== 'undefined' && Chart.instances) {
      Object.values(Chart.instances).forEach(chart => {
        if (chart && typeof chart.resize === 'function') chart.resize();
      });
    }
    Object.values(chartInstances).forEach(chart => {
      if (chart && typeof chart.resize === 'function') chart.resize();
    });
  }

  function nextSlide() {
    if (currentSlide < totalSlides) {
      currentSlide++;
      updateSlides();
    }
  }

  function prevSlide() {
    if (currentSlide > 1) {
      currentSlide--;
      updateSlides();
    }
  }

  function toggleFullScreen() {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
    } else {
      if (document.exitFullscreen) document.exitFullscreen().catch(() => {});
    }
  }

  // 5. INJEÇÃO AUTOMÁTICA DOS CONTROLES DO APRESENTADOR
  function ensureControls() {
    if (!document.body) {
      setTimeout(ensureControls, 30);
      return;
    }
    let controls = document.querySelector('.deck-controls');
    if (!controls) {
      controls = document.createElement('div');
      controls.className = 'deck-controls';
      controls.innerHTML = `
        <button id="btnPrev">← Anterior</button>
        <span id="slideIndicator" style="padding-inline: 8px;">Slide 1 / ${totalSlides}</span>
        <button id="btnNext">Próximo →</button>
        <button class="btn-sec btn-solar" id="btnFS">F11 Tela Cheia</button>
        <button class="btn-sec" id="btnPDF" title="Baixar Apresentação Convertida em PDF">Exportar PDF</button>
        <button class="btn-sec" id="btnPPTX" title="Baixar Apresentação em PowerPoint Editável">Exportar PPTX</button>
      `;
      document.body.appendChild(controls);

      document.getElementById('btnPrev').addEventListener('click', prevSlide);
      document.getElementById('btnNext').addEventListener('click', nextSlide);
      document.getElementById('btnFS').addEventListener('click', toggleFullScreen);
      document.getElementById('btnPDF').addEventListener('click', exportPDF);
      document.getElementById('btnPPTX').addEventListener('click', exportPPTX);
    }
  }

  // Função utilitária para carregamento dinâmico de scripts
  function loadScript(src) {
    return new Promise((resolve, reject) => {
      const existing = document.querySelector(`script[src="${src}"]`);
      if (existing) return resolve();
      const s = document.createElement('script');
      s.src = src;
      s.onload = () => resolve();
      s.onerror = (err) => reject(err);
      document.head.appendChild(s);
    });
  }

  // Helper para calcular coordenadas em polegadas (10 x 5.625) relativas ao slide
  function getBox(el, slideRect) {
    const r = el.getBoundingClientRect();
    return {
      x: ((r.left - slideRect.left) / slideRect.width) * 10,
      y: ((r.top - slideRect.top) / slideRect.height) * 5.625,
      w: (r.width / slideRect.width) * 10,
      h: (r.height / slideRect.height) * 5.625
    };
  }

  // Helper para calcular coordenadas em pixels widescreen (1920 x 1080) relativas ao slide para jsPDF
  function getPixelBox(el, slideRect) {
    const r = el.getBoundingClientRect();
    return {
      x: ((r.left - slideRect.left) / slideRect.width) * 1920,
      y: ((r.top - slideRect.top) / slideRect.height) * 1080,
      w: (r.width / slideRect.width) * 1920,
      h: (r.height / slideRect.height) * 1080
    };
  }

  // Helper para localizar instância ativa do Chart.js vinculada a um elemento <canvas>
  function getChartInstance(canvas) {
    if (typeof Chart === 'undefined') return null;
    if (Chart.instances) {
      for (const key of Object.keys(Chart.instances)) {
        const inst = Chart.instances[key];
        if (inst && (inst.canvas === canvas || (inst.canvas && inst.canvas.id === canvas.id))) {
          return inst;
        }
      }
    }
    if (typeof Chart.getChart === 'function') {
      try {
        const c = Chart.getChart(canvas) || Chart.getChart(canvas.id);
        if (c) return c;
      } catch (e) {}
    }
    return null;
  }

  // Helper para forçar a renderização completa e síncrona de um gráfico Chart.js mesmo se criado em slide inativo
  function prepareCanvasChart(canvas) {
    const chart = getChartInstance(canvas);
    const parent = canvas.parentElement;
    const targetW = (parent && parent.clientWidth > 50) ? parent.clientWidth : (canvas.clientWidth || 750);
    const targetH = (parent && parent.clientHeight > 50) ? parent.clientHeight : (canvas.clientHeight || 380);

    // Se as dimensões do canvas estiverem zeradas devido ao slide inativo (display: none)
    if (canvas.width === 0 || canvas.height === 0 || canvas.offsetWidth === 0 || canvas.offsetHeight === 0) {
      canvas.style.width = targetW + 'px';
      canvas.style.height = targetH + 'px';
      canvas.width = targetW;
      canvas.height = targetH;
    }

    if (chart) {
      try {
        chart.resize(targetW, targetH);
        chart.update('none'); // Renderização síncrona sem animação
      } catch (err) {}
    }

    return chart;
  }

  // 6. EXPORTAÇÃO INTELIGENTE DE APRESENTAÇÃO POWERPOINT (.PPTX) EM CAMADAS NATIVAS
  // Decompõe elementos HTML em formas, caixas de texto Segoe UI, tabelas nativas e gráficos transparentes
  async function exportPPTX() {
    const btn = document.getElementById('btnPPTX');
    const originalText = btn ? btn.innerText : 'Exportar PPTX';
    if (btn) {
      btn.innerText = 'Iniciando PPTX...';
      btn.disabled = true;
    }

    try {
      if (typeof window.PptxGenJS === 'undefined') {
        await loadScript('https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/dist/pptxgen.bundle.js');
      }

      const PptxConstructor = window.PptxGenJS;
      if (!PptxConstructor) {
        throw new Error('A biblioteca PptxGenJS não pôde ser inicializada no navegador.');
      }
      const pptx = new PptxConstructor();
      pptx.layout = 'LAYOUT_16x9';
      pptx.author = 'Governo do Estado de Goiás — Secretaria da Economia';
      pptx.company = 'Secretaria da Economia de Goiás';
      pptx.title = document.title || 'Apresentação Orçamentária';

      const slides = Array.from(document.querySelectorAll('.slide'));
      const total = slides.length;
      const originalSlide = currentSlide;

      for (let i = 0; i < total; i++) {
        const slide = slides[i];
        if (btn) btn.innerText = `Gerando Camadas ${i + 1}/${total}...`;

        // REGRA INVIOLÁVEL: Último slide (encerramento) é 100% limpo, apenas imagem oficial
        if (slide.classList.contains('slide-closing')) {
          const pSlide = pptx.addSlide();
          pSlide.addImage({
            data: ASSETS.encerramento,
            x: 0,
            y: 0,
            w: 10,
            h: 5.625
          });
          continue;
        }

        // Prepara slide temporariamente para medições exatas em 1920x1080
        const prevActive = slide.classList.contains('active');
        slides.forEach(s => s.classList.remove('active'));
        slide.classList.add('active');

        slide.style.setProperty('display', 'flex', 'important');
        slide.style.setProperty('visibility', 'visible', 'important');
        slide.style.setProperty('opacity', '1', 'important');
        slide.style.setProperty('transform', 'none', 'important');
        slide.style.setProperty('position', 'fixed', 'important');
        slide.style.setProperty('top', '0', 'important');
        slide.style.setProperty('left', '0', 'important');
        slide.style.setProperty('width', '1920px', 'important');
        slide.style.setProperty('height', '1080px', 'important');
        slide.style.setProperty('z-index', '99999', 'important');

        try {
          const slideRect = slide.getBoundingClientRect();
          const pSlide = pptx.addSlide();
          const handledElements = new Set();

          // CAMADA 1: FUNDO OFICIAL DO SLIDE
          const isCover = slide.classList.contains('slide-cover');
          if (isCover) {
            pSlide.background = { color: 'F2F6F3' };
          } else {
            pSlide.addImage({
              data: ASSETS.bgConteudo,
              x: 0,
              y: 0,
              w: 10,
              h: 5.625
            });
          }

          // CAMADA 2: CABEÇALHO / TOPBAR (BREADCRUMB, TÍTULO, SUBTÍTULO)
          const breadcrumb = slide.querySelector('.slide-breadcrumb, .breadcrumb');
          if (breadcrumb && breadcrumb.innerText.trim()) {
            handledElements.add(breadcrumb);
            breadcrumb.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getBox(breadcrumb, slideRect);
            pSlide.addText(breadcrumb.innerText.trim().toUpperCase(), {
              x: box.x,
              y: box.y,
              w: Math.max(box.w, 4),
              h: Math.max(box.h, 0.28),
              fontFace: 'Segoe UI',
              fontSize: 10,
              bold: true,
              color: '15542A',
              margin: 0,
              valign: 'middle'
            });
          }

          const titleEl = slide.querySelector('.slide-title, .slide-header h2, h2, h1');
          if (titleEl && titleEl.innerText.trim()) {
            handledElements.add(titleEl);
            titleEl.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getBox(titleEl, slideRect);
            pSlide.addText(titleEl.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: Math.max(box.w, 6),
              h: Math.max(box.h, 0.45),
              fontFace: 'Segoe UI',
              fontSize: isCover ? 28 : 20,
              bold: true,
              color: '0B3017',
              margin: 0,
              valign: 'top',
              wrap: true
            });
          }

          const subEl = slide.querySelector('.slide-topbar p, .slide-subtitle, .header-desc');
          if (subEl && subEl.innerText.trim()) {
            handledElements.add(subEl);
            subEl.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getBox(subEl, slideRect);
            pSlide.addText(subEl.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: Math.max(box.w, 6),
              h: Math.max(box.h, 0.35),
              fontFace: 'Segoe UI',
              fontSize: 11,
              color: '4B5563',
              margin: 0,
              valign: 'top',
              wrap: true
            });
          }

          // CAMADA 3: TABELAS NATIVAS EDITÁVEIS
          const tables = Array.from(slide.querySelectorAll('table'));
          tables.forEach(table => {
            handledElements.add(table);
            table.querySelectorAll('*').forEach(child => handledElements.add(child));
            const box = getBox(table, slideRect);
            const rows = [];
            const trs = Array.from(table.querySelectorAll('tr'));
            trs.forEach((tr, rIdx) => {
              const rowCells = [];
              const isHeader = tr.querySelector('th') !== null || rIdx === 0;
              const cells = Array.from(tr.querySelectorAll('th, td'));
              cells.forEach(cell => {
                const text = cell.innerText.trim();
                rowCells.push({
                  text: text,
                  options: {
                    fontFace: 'Segoe UI',
                    fontSize: isHeader ? 10 : 9.5,
                    bold: isHeader,
                    color: isHeader ? 'FFFFFF' : '0D1711',
                    fill: isHeader ? { color: '0B3017' } : { color: (rIdx % 2 === 0 ? 'F9FBF9' : 'FFFFFF') },
                    align: cell.style.textAlign || (isNaN(text.replace(/[^0-9]/g, '')) ? 'left' : 'right'),
                    valign: 'middle',
                    border: { type: 'solid', pt: 1, color: 'E5E7EB' }
                  }
                });
              });
              if (rowCells.length > 0) rows.push(rowCells);
            });
            if (rows.length > 0) {
              pSlide.addTable(rows, {
                x: box.x,
                y: box.y,
                w: box.w,
                h: box.h,
                margin: 3
              });
            }
          });

          // CAMADA 4: CARDS / CONTAINERS (FORMAS NATIVAS POWERPOINT)
          const cardSelectors = '.card, .card-soft-sage, .card-elevated-green, .card-solar-cta, .card-kpi, .chart-card, .table-box, .stat-card, .highlight-box';
          const cards = Array.from(slide.querySelectorAll(cardSelectors));
          cards.forEach(card => {
            if (card.offsetWidth <= 0 || card.offsetHeight <= 0) return;
            const box = getBox(card, slideRect);
            const style = window.getComputedStyle(card);

            let fillHex = parseColorToHex(style.backgroundColor, 'FFFFFF');
            let borderHex = parseColorToHex(style.borderColor, 'E5E7EB');
            let hasBorder = parseFloat(style.borderWidth) > 0 && style.borderStyle !== 'none';

            if (card.classList.contains('card-elevated-green')) {
              fillHex = '0B3017';
              borderHex = '15542A';
            } else if (card.classList.contains('card-solar-cta')) {
              fillHex = 'FEE000';
              borderHex = 'D4B800';
            } else if (card.classList.contains('card-soft-sage')) {
              fillHex = 'EBF5EE';
              borderHex = 'C5E0D0';
            } else if (card.classList.contains('card-kpi') || card.classList.contains('chart-card') || card.classList.contains('table-box')) {
              fillHex = 'FFFFFF';
              borderHex = 'E5E7EB';
            }

            pSlide.addShape(pptx.ShapeType.roundRect, {
              x: box.x,
              y: box.y,
              w: box.w,
              h: box.h,
              fill: { color: fillHex },
              line: hasBorder ? { color: borderHex, width: 1 } : undefined,
              rectRadius: 0.08
            });
          });

          // CAMADA 5: GRÁFICOS TRANSPARENTES SOBREPOSTOS AOS CARDS
          const canvases = Array.from(slide.querySelectorAll('canvas'));
          canvases.forEach(canvas => {
            handledElements.add(canvas);
            try {
              prepareCanvasChart(canvas);
              const box = getBox(canvas, slideRect);
              if (box.w > 0.1 && box.h > 0.1) {
                const dataUrl = canvas.toDataURL('image/png');
                if (dataUrl && dataUrl.length > 50 && dataUrl.startsWith('data:image/png')) {
                  pSlide.addImage({
                    data: dataUrl,
                    x: box.x,
                    y: box.y,
                    w: box.w,
                    h: box.h
                  });
                }
              }
            } catch (err) {
              console.warn('Erro ao extrair imagem do canvas para PPTX:', err);
            }
          });

          // CAMADA 5.1: IMAGENS EXTERNAS (IMG)
          const images = Array.from(slide.querySelectorAll('img'));
          images.forEach(img => {
            if (handledElements.has(img) || img.offsetWidth <= 0 || img.offsetHeight <= 0) return;
            handledElements.add(img);
            try {
              const box = getBox(img, slideRect);
              if (box.w > 0.1 && box.h > 0.1 && img.src) {
                pSlide.addImage({
                  data: img.src,
                  x: box.x,
                  y: box.y,
                  w: box.w,
                  h: box.h
                });
              }
            } catch (imgErr) {
              console.warn('Erro ao inserir imagem no PPTX:', imgErr);
            }
          });

          // CAMADA 6: BADGES (PÍLULAS NATIVAS)
          const badges = Array.from(slide.querySelectorAll('.badge, .status-badge'));
          badges.forEach(badge => {
            if (handledElements.has(badge) || badge.offsetWidth <= 0) return;
            handledElements.add(badge);
            badge.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getBox(badge, slideRect);
            const style = window.getComputedStyle(badge);
            const fillHex = parseColorToHex(style.backgroundColor, 'EDF8F0');
            const borderHex = parseColorToHex(style.borderColor, 'ADE0BA');
            const textHex = parseColorToHex(style.color, '16642F');

            pSlide.addShape(pptx.ShapeType.roundRect, {
              x: box.x,
              y: box.y,
              w: box.w,
              h: box.h,
              fill: { color: fillHex },
              line: { color: borderHex, width: 1 },
              rectRadius: 0.2
            });

            pSlide.addText(badge.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: box.w,
              h: box.h,
              fontFace: 'Segoe UI',
              fontSize: 9,
              bold: true,
              color: textHex,
              align: 'center',
              valign: 'middle'
            });
          });

          // CAMADA 7: INDICADORES E MÉTRICAS KPI (NATIVAS)
          const kpiVals = Array.from(slide.querySelectorAll('.kpi-val, .kpi-value, .stat-value'));
          kpiVals.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            handledElements.add(el);
            const box = getBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pSlide.addText(el.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: Math.max(box.w, 1.5),
              h: Math.max(box.h, 0.45),
              fontFace: 'Segoe UI',
              fontSize: 22,
              bold: true,
              color: isDark ? 'FFFFFF' : '0B3017',
              margin: 0,
              valign: 'middle'
            });
          });

          const kpiLabels = Array.from(slide.querySelectorAll('.kpi-label, .stat-label'));
          kpiLabels.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            handledElements.add(el);
            const box = getBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pSlide.addText(el.innerText.trim().toUpperCase(), {
              x: box.x,
              y: box.y,
              w: Math.max(box.w, 1.5),
              h: Math.max(box.h, 0.25),
              fontFace: 'Segoe UI',
              fontSize: 9.5,
              bold: true,
              color: isDark ? 'ADE0BA' : '15542A',
              margin: 0,
              valign: 'middle'
            });
          });

          const kpiSubs = Array.from(slide.querySelectorAll('.kpi-sub, .stat-sub'));
          kpiSubs.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            handledElements.add(el);
            const box = getBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pSlide.addText(el.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: Math.max(box.w, 1.5),
              h: Math.max(box.h, 0.25),
              fontFace: 'Segoe UI',
              fontSize: 9,
              color: isDark ? 'D5EEDC' : '6B7280',
              margin: 0,
              valign: 'middle'
            });
          });

          // CAMADA 8: TÍTULOS DE CARDS (H3, H4, .CARD-TITLE)
          const cardTitles = Array.from(slide.querySelectorAll('h3, h4, .card-title'));
          cardTitles.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            handledElements.add(el);
            const box = getBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pSlide.addText(el.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: box.w,
              h: Math.max(box.h, 0.35),
              fontFace: 'Segoe UI',
              fontSize: 12.5,
              bold: true,
              color: isDark ? 'FFFFFF' : '0B3017',
              margin: 0,
              valign: 'top',
              wrap: true
            });
          });

          // CAMADA 9: PARÁGRAFOS E TEXTOS DE CORPO
          const paragraphs = Array.from(slide.querySelectorAll('p'));
          paragraphs.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0 || !el.innerText.trim()) return;
            handledElements.add(el);
            const box = getBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pSlide.addText(el.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: box.w,
              h: box.h,
              fontFace: 'Segoe UI',
              fontSize: 10,
              color: isDark ? 'EBF5EE' : '4B5563',
              margin: 0,
              valign: 'top',
              wrap: true
            });
          });

          // CAMADA 10: LISTAS BULLET POINT
          const lists = Array.from(slide.querySelectorAll('ul, ol'));
          lists.forEach(list => {
            if (handledElements.has(list) || list.offsetWidth <= 0) return;
            handledElements.add(list);
            const items = Array.from(list.querySelectorAll('li'));
            if (items.length === 0) return;

            const isDark = list.closest('.card-elevated-green') !== null;
            const listItems = items.map(li => {
              handledElements.add(li);
              return {
                text: li.innerText.trim(),
                options: {
                  fontFace: 'Segoe UI',
                  fontSize: 10,
                  color: isDark ? 'EBF5EE' : '4B5563',
                  bullet: true,
                  breakLine: true
                }
              };
            });

            const box = getBox(list, slideRect);
            pSlide.addText(listItems, {
              x: box.x,
              y: box.y,
              w: box.w,
              h: box.h,
              margin: 0,
              valign: 'top'
            });
          });

          // CAMADA 11: RODAPÉ INSTITUCIONAL
          const footers = Array.from(slide.querySelectorAll('.slide-footer span'));
          footers.forEach(span => {
            if (handledElements.has(span) || span.offsetWidth <= 0 || !span.innerText.trim()) return;
            handledElements.add(span);
            const box = getBox(span, slideRect);
            pSlide.addText(span.innerText.trim(), {
              x: box.x,
              y: box.y,
              w: box.w,
              h: Math.max(box.h, 0.25),
              fontFace: 'Segoe UI',
              fontSize: 8.5,
              color: '4B5563',
              margin: 0,
              valign: 'middle'
            });
          });

          // CAMADA 12: ELEMENTOS DE TEXTO RESIDUAIS
          slide.querySelectorAll('div, span, small').forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            if (el.children.length === 0 && el.innerText.trim().length > 0) {
              handledElements.add(el);
              const box = getBox(el, slideRect);
              if (box.w > 0.2 && box.h > 0.1) {
                const isDark = el.closest('.card-elevated-green') !== null;
                pSlide.addText(el.innerText.trim(), {
                  x: box.x,
                  y: box.y,
                  w: box.w,
                  h: box.h,
                  fontFace: 'Segoe UI',
                  fontSize: 9.5,
                  color: isDark ? 'EBF5EE' : '4B5563',
                  margin: 0,
                  valign: 'top',
                  wrap: true
                });
              }
            }
          });

        } catch (captureErr) {
          console.warn(`Erro na exportação em camadas do slide ${i + 1}:`, captureErr);
        } finally {
          slide.style.removeProperty('display');
          slide.style.removeProperty('visibility');
          slide.style.removeProperty('opacity');
          slide.style.removeProperty('transform');
          slide.style.removeProperty('position');
          slide.style.removeProperty('top');
          slide.style.removeProperty('left');
          slide.style.removeProperty('width');
          slide.style.removeProperty('height');
          slide.style.removeProperty('z-index');
          if (!prevActive) slide.classList.remove('active');
        }
      }

      currentSlide = originalSlide;
      updateSlides();

      if (btn) btn.innerText = 'Baixando PPTX...';
      const cleanTitle = (document.title || 'Apresentacao-Orcamentaria')
        .replace(/[^a-zA-Z0-9À-ÿ_-]/g, '_')
        .substring(0, 35);
      await pptx.writeFile({ fileName: `${cleanTitle}.pptx` });

    } catch (err) {
      console.error('Falha na exportação PPTX:', err);
      alert('Não foi possível gerar o arquivo PowerPoint. Detalhes: ' + (err && err.message ? err.message : err));
    } finally {
      if (btn) {
        btn.innerText = originalText;
        btn.disabled = false;
      }
    }
  }

  // 7. EXPORTAÇÃO INTELIGENTE DE APRESENTAÇÃO EM ARQUIVO PDF NATIVO (.PDF) EM VETOR DIRETO
  // Decompõe elementos do DOM diretamente em instruções vetoriais do jsPDF (sem html2canvas, sem rasterização, sem canvas tainted)
  async function exportPDF() {
    const btn = document.getElementById('btnPDF');
    const originalText = btn ? btn.innerText : 'Exportar PDF';
    if (btn) {
      btn.innerText = 'Iniciando PDF...';
      btn.disabled = true;
    }

    try {
      if (typeof window.jspdf === 'undefined' && typeof window.jsPDF === 'undefined') {
        await loadScript('https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js');
      }

      const JsPdfConstructor = (window.jspdf && window.jspdf.jsPDF) || window.jsPDF;
      if (!JsPdfConstructor) {
        throw new Error('A biblioteca jsPDF não pôde ser inicializada no navegador.');
      }
      const pdf = new JsPdfConstructor({
        orientation: 'landscape',
        unit: 'px',
        format: [1920, 1080],
        hotfixes: ['px_scaling']
      });

      const slides = Array.from(document.querySelectorAll('.slide'));
      const total = slides.length;
      const originalSlide = currentSlide;

      for (let i = 0; i < total; i++) {
        const slide = slides[i];
        if (btn) btn.innerText = `Gerando PDF ${i + 1}/${total}...`;

        if (i > 0) {
          pdf.addPage([1920, 1080], 'landscape');
        }

        // REGRA INVIOLÁVEL: Último slide (encerramento) é 100% limpo, apenas imagem oficial
        if (slide.classList.contains('slide-closing')) {
          pdf.addImage(ASSETS.encerramento, 'PNG', 0, 0, 1920, 1080, undefined, 'FAST');
          continue;
        }

        // Prepara slide temporariamente para medições exatas em 1920x1080
        const prevActive = slide.classList.contains('active');
        slides.forEach(s => s.classList.remove('active'));
        slide.classList.add('active');

        slide.style.setProperty('display', 'flex', 'important');
        slide.style.setProperty('visibility', 'visible', 'important');
        slide.style.setProperty('opacity', '1', 'important');
        slide.style.setProperty('transform', 'none', 'important');
        slide.style.setProperty('position', 'fixed', 'important');
        slide.style.setProperty('top', '0', 'important');
        slide.style.setProperty('left', '0', 'important');
        slide.style.setProperty('width', '1920px', 'important');
        slide.style.setProperty('height', '1080px', 'important');
        slide.style.setProperty('z-index', '99999', 'important');

        try {
          const slideRect = slide.getBoundingClientRect();
          const isCover = slide.classList.contains('slide-cover');
          const handledElements = new Set();

          // Ignora SVGs e caixas decorativas de ícone como texto direto
          slide.querySelectorAll('svg, .icon-box-sage, .kpi-icon').forEach(el => handledElements.add(el));

          // 1. FUNDO OFICIAL DO SLIDE
          if (isCover) {
            pdf.setFillColor(242, 246, 243);
            pdf.rect(0, 0, 1920, 1080, 'F');
          } else {
            pdf.addImage(ASSETS.bgConteudo, 'PNG', 0, 0, 1920, 1080, undefined, 'FAST');
          }

          // 2. CABEÇALHO / TOPBAR (BREADCRUMB, TÍTULO, SUBTÍTULO)
          const breadcrumb = slide.querySelector('.slide-breadcrumb, .breadcrumb');
          if (breadcrumb && breadcrumb.innerText.trim()) {
            handledElements.add(breadcrumb);
            breadcrumb.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getPixelBox(breadcrumb, slideRect);
            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(13);
            pdf.setTextColor(21, 84, 42); // #15542A
            pdf.text(breadcrumb.innerText.trim().toUpperCase(), box.x, box.y + 13);
          }

          const titleEl = slide.querySelector('.slide-title, .slide-header h2, .slide-header h1, h1');
          if (titleEl && titleEl.innerText.trim()) {
            handledElements.add(titleEl);
            titleEl.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getPixelBox(titleEl, slideRect);
            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(isCover ? 38 : 28);
            pdf.setTextColor(11, 48, 23); // #0B3017
            const titleLines = pdf.splitTextToSize(titleEl.innerText.trim(), box.w > 50 ? box.w : 1400);
            pdf.text(titleLines, box.x, box.y + (isCover ? 34 : 26));
          }

          const subEl = slide.querySelector('.slide-topbar p, .slide-subtitle, .header-desc');
          if (subEl && subEl.innerText.trim()) {
            handledElements.add(subEl);
            subEl.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getPixelBox(subEl, slideRect);
            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(15);
            pdf.setTextColor(75, 85, 99);
            const subLines = pdf.splitTextToSize(subEl.innerText.trim(), box.w > 50 ? box.w : 1400);
            pdf.text(subLines, box.x, box.y + 14);
          }

          // 3. CARDS E CONTAINERS (FORMAS VETORIAIS COM BORDAS E CANTOS ARREDONDADOS)
          const cardSelectors = '.card, .card-soft-sage, .card-elevated-green, .card-solar-cta, .card-kpi, .chart-card, .table-box, .stat-card, .highlight-box';
          const cards = Array.from(slide.querySelectorAll(cardSelectors));
          cards.forEach(card => {
            if (card.offsetWidth <= 0 || card.offsetHeight <= 0) return;
            const box = getPixelBox(card, slideRect);
            const style = window.getComputedStyle(card);

            let bgRgb = parseColorToRgb(style.backgroundColor, [255, 255, 255]);
            let borderRgb = parseColorToRgb(style.borderColor, [229, 231, 235]);

            if (card.classList.contains('card-elevated-green')) {
              bgRgb = [11, 48, 23];
              borderRgb = [21, 84, 42];
            } else if (card.classList.contains('card-solar-cta')) {
              bgRgb = [254, 224, 0];
              borderRgb = [212, 184, 0];
            } else if (card.classList.contains('card-soft-sage')) {
              bgRgb = [235, 245, 238];
              borderRgb = [197, 224, 208];
            } else if (card.classList.contains('card-kpi') || card.classList.contains('chart-card') || card.classList.contains('table-box')) {
              bgRgb = [255, 255, 255];
              borderRgb = [229, 231, 235];
            }

            pdf.setFillColor(bgRgb[0], bgRgb[1], bgRgb[2]);
            pdf.setDrawColor(borderRgb[0], borderRgb[1], borderRgb[2]);
            pdf.setLineWidth(1.5);
            pdf.roundedRect(box.x, box.y, box.w, box.h, 10, 10, 'FD');
          });

          // 4. GRÁFICOS TRANSPARENTES (CHART.JS CANVAS VIA 2D BITMAP)
          const canvases = Array.from(slide.querySelectorAll('canvas'));
          canvases.forEach(canvas => {
            handledElements.add(canvas);
            try {
              prepareCanvasChart(canvas);
              const box = getPixelBox(canvas, slideRect);
              if (box.w > 10 && box.h > 10) {
                const dataUrl = canvas.toDataURL('image/png');
                if (dataUrl && dataUrl.length > 50 && dataUrl.startsWith('data:image/png')) {
                  pdf.addImage(dataUrl, 'PNG', box.x, box.y, box.w, box.h, undefined, 'FAST');
                }
              }
            } catch (canvasErr) {
              console.warn('Erro ao extrair imagem do canvas para PDF:', canvasErr);
            }
          });

          // 4.1. IMAGENS (IMG)
          const images = Array.from(slide.querySelectorAll('img'));
          images.forEach(img => {
            if (handledElements.has(img) || img.offsetWidth <= 0 || img.offsetHeight <= 0) return;
            handledElements.add(img);
            try {
              const box = getPixelBox(img, slideRect);
              if (box.w > 10 && box.h > 10 && img.src) {
                pdf.addImage(img.src, 'PNG', box.x, box.y, box.w, box.h, undefined, 'FAST');
              }
            } catch (imgErr) {
              console.warn('Erro ao inserir imagem no PDF:', imgErr);
            }
          });

          // 5. BADGES E TAGS EM PÍLULA
          const badges = Array.from(slide.querySelectorAll('.badge, .status-badge, .ne-badge, .kpi-tag-success, .kpi-tag-alert, .kpi-tag-info, [class*="kpi-tag"]'));
          badges.forEach(badge => {
            if (handledElements.has(badge) || badge.offsetWidth <= 0) return;
            handledElements.add(badge);
            badge.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getPixelBox(badge, slideRect);
            const style = window.getComputedStyle(badge);

            let bgRgb = parseColorToRgb(style.backgroundColor, [237, 248, 240]);
            let borderRgb = parseColorToRgb(style.borderColor, [173, 224, 186]);
            let textRgb = parseColorToRgb(style.color, [22, 100, 47]);

            if (badge.classList.contains('kpi-tag-success')) {
              bgRgb = [237, 248, 240];
              borderRgb = [173, 224, 186];
              textRgb = [22, 100, 47];
            } else if (badge.classList.contains('kpi-tag-alert')) {
              bgRgb = [254, 242, 242];
              borderRgb = [254, 202, 202];
              textRgb = [185, 28, 28];
            }

            pdf.setFillColor(bgRgb[0], bgRgb[1], bgRgb[2]);
            pdf.setDrawColor(borderRgb[0], borderRgb[1], borderRgb[2]);
            pdf.setLineWidth(1);
            pdf.roundedRect(box.x, box.y, box.w, box.h, box.h / 2, box.h / 2, 'FD');

            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(11);
            pdf.setTextColor(textRgb[0], textRgb[1], textRgb[2]);
            pdf.text(badge.innerText.trim(), box.x + (box.w / 2), box.y + (box.h / 2) + 4, { align: 'center' });
          });

          // 6. INDICADORES E MÉTRICAS KPI (NATIVAS)
          const kpiVals = Array.from(slide.querySelectorAll('.kpi-val, .kpi-value, .stat-value'));
          kpiVals.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            handledElements.add(el);
            const box = getPixelBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(36);
            if (isDark) pdf.setTextColor(255, 255, 255);
            else pdf.setTextColor(11, 48, 23);
            pdf.text(el.innerText.trim(), box.x, box.y + 32);
          });

          const kpiLabels = Array.from(slide.querySelectorAll('.kpi-label, .stat-label, .card-label'));
          kpiLabels.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            handledElements.add(el);
            const box = getPixelBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            const isSolar = el.closest('.card-solar-cta') !== null;
            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(13);
            if (isDark) pdf.setTextColor(173, 224, 186); // #ade0ba
            else if (isSolar) pdf.setTextColor(115, 102, 0); // #736600
            else pdf.setTextColor(21, 84, 42); // #15542a
            pdf.text(el.innerText.trim().toUpperCase(), box.x, box.y + 12);
          });

          const kpiSubs = Array.from(slide.querySelectorAll('.kpi-sub, .stat-sub'));
          kpiSubs.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0) return;
            handledElements.add(el);
            const box = getPixelBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(12);
            if (isDark) pdf.setTextColor(235, 245, 238);
            else pdf.setTextColor(107, 114, 128);
            pdf.text(el.innerText.trim(), box.x, box.y + 12);
          });

          // 7. BARRAS DE PROGRESSO KPI VETORIAIS
          const progressBars = Array.from(slide.querySelectorAll('.kpi-progress-bar'));
          progressBars.forEach(pBar => {
            if (handledElements.has(pBar) || pBar.offsetWidth <= 0) return;
            handledElements.add(pBar);
            pBar.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getPixelBox(pBar, slideRect);
            pdf.setFillColor(229, 231, 235); // #E5E7EB
            pdf.roundedRect(box.x, box.y, box.w, box.h, box.h / 2, box.h / 2, 'F');
            const fillEl = pBar.querySelector('.kpi-progress-fill');
            if (fillEl) {
              const fillW = Math.min(box.w, (fillEl.offsetWidth / (pBar.offsetWidth || 1)) * box.w);
              if (fillW > 0) {
                pdf.setFillColor(33, 150, 71); // #219647
                pdf.roundedRect(box.x, box.y, fillW, box.h, box.h / 2, box.h / 2, 'F');
              }
            }
          });

          // 8. TÍTULOS DE CARDS E SUB-SEÇÕES (H2, H3, H4, .CARD-TITLE)
          const headings = Array.from(slide.querySelectorAll('h2, h3, h4, .card-title'));
          headings.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0 || !el.innerText.trim()) return;
            handledElements.add(el);
            const box = getPixelBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            const isSolar = el.closest('.card-solar-cta') !== null;
            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(18);
            if (isDark) pdf.setTextColor(255, 255, 255);
            else if (isSolar) pdf.setTextColor(11, 48, 23);
            else pdf.setTextColor(11, 48, 23);
            const lines = pdf.splitTextToSize(el.innerText.trim(), box.w > 40 ? box.w : 500);
            pdf.text(lines, box.x, box.y + 18);
          });

          // 9. BOTÕES DE AÇÃO (.BTN-WHITE, .BTN-GREEN-CTA, .BTN)
          const actionButtons = Array.from(slide.querySelectorAll('button, .btn, .btn-white, .btn-green-cta, .cta-btn'));
          actionButtons.forEach(btnEl => {
            if (handledElements.has(btnEl) || btnEl.offsetWidth <= 0 || !btnEl.innerText.trim()) return;
            handledElements.add(btnEl);
            btnEl.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getPixelBox(btnEl, slideRect);
            const isSolar = btnEl.classList.contains('btn-green-cta');
            const isWhite = btnEl.classList.contains('btn-white');

            if (isSolar) {
              pdf.setFillColor(11, 48, 23); // #0B3017
              pdf.setTextColor(255, 255, 255);
            } else if (isWhite) {
              pdf.setFillColor(255, 255, 255);
              pdf.setTextColor(11, 48, 23);
            } else {
              pdf.setFillColor(33, 150, 71); // #219647
              pdf.setTextColor(255, 255, 255);
            }

            pdf.roundedRect(box.x, box.y, box.w, box.h, 6, 6, 'F');
            pdf.setFont('helvetica', 'bold');
            pdf.setFontSize(13);
            pdf.text(btnEl.innerText.trim(), box.x + (box.w / 2), box.y + (box.h / 2) + 4, { align: 'center' });
          });

          // 10. PARÁGRAFOS E TEXTOS DESCRITIVOS (P, .CARD-DESC, .KPI-PROGRESS-TEXT)
          const paragraphs = Array.from(slide.querySelectorAll('p, .card-desc, .kpi-progress-text'));
          paragraphs.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0 || !el.innerText.trim()) return;
            handledElements.add(el);
            const box = getPixelBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            const isSolar = el.closest('.card-solar-cta') !== null;
            const isProgressText = el.classList.contains('kpi-progress-text');

            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(isProgressText ? 12 : 15);
            if (isDark) pdf.setTextColor(235, 245, 238);
            else if (isSolar) pdf.setTextColor(61, 55, 0);
            else pdf.setTextColor(75, 85, 99);

            const lines = pdf.splitTextToSize(el.innerText.trim(), box.w > 30 ? box.w : 500);
            pdf.text(lines, box.x, box.y + (isProgressText ? 11 : 14));
          });

          // 11. LISTAS (UL, OL COM BULLETS)
          const lists = Array.from(slide.querySelectorAll('ul, ol'));
          lists.forEach(list => {
            if (handledElements.has(list) || list.offsetWidth <= 0) return;
            handledElements.add(list);
            const items = Array.from(list.querySelectorAll('li'));
            if (items.length === 0) return;
            const isDark = list.closest('.card-elevated-green') !== null;
            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(14);
            if (isDark) pdf.setTextColor(235, 245, 238);
            else pdf.setTextColor(75, 85, 99);

            let curY = getPixelBox(list, slideRect).y + 14;
            items.forEach(li => {
              handledElements.add(li);
              const text = '• ' + li.innerText.trim();
              const lines = pdf.splitTextToSize(text, getPixelBox(list, slideRect).w);
              pdf.text(lines, getPixelBox(list, slideRect).x, curY);
              curY += (lines.length * 20);
            });
          });

          // 12. TABELAS NATIVAS EDITÁVEIS
          const tables = Array.from(slide.querySelectorAll('table'));
          tables.forEach(table => {
            handledElements.add(table);
            table.querySelectorAll('*').forEach(c => handledElements.add(c));
            const box = getPixelBox(table, slideRect);
            const trs = Array.from(table.querySelectorAll('tr'));
            if (trs.length === 0) return;
            let rowY = box.y;
            const rowH = box.h / trs.length;

            trs.forEach((tr, rIdx) => {
              const isHeader = tr.querySelector('th') !== null || rIdx === 0;
              const cells = Array.from(tr.querySelectorAll('th, td'));
              if (cells.length === 0) return;
              let cellX = box.x;
              const cellW = box.w / cells.length;

              cells.forEach(cell => {
                if (isHeader) {
                  pdf.setFillColor(11, 48, 23); // #0B3017
                  pdf.setDrawColor(21, 84, 42);
                } else {
                  pdf.setFillColor(rIdx % 2 === 0 ? 249 : 255, rIdx % 2 === 0 ? 251 : 255, rIdx % 2 === 0 ? 249 : 255);
                  pdf.setDrawColor(229, 231, 235);
                }
                pdf.setLineWidth(1);
                pdf.rect(cellX, rowY, cellW, rowH, 'FD');

                pdf.setFont('helvetica', isHeader ? 'bold' : 'normal');
                pdf.setFontSize(isHeader ? 12 : 11);
                if (isHeader) pdf.setTextColor(255, 255, 255);
                else pdf.setTextColor(13, 23, 17);

                const align = cell.style.textAlign || 'left';
                const txt = cell.innerText.trim();
                let textX = cellX + 12;
                if (align === 'right') textX = cellX + cellW - 12;
                else if (align === 'center') textX = cellX + (cellW / 2);

                pdf.text(txt, textX, rowY + (rowH / 2) + 4, { align: align });
                cellX += cellW;
              });
              rowY += rowH;
            });
          });

          // 13. RODAPÉS INSTITUCIONAIS
          const footers = Array.from(slide.querySelectorAll('.slide-footer span, .slide-footer div'));
          footers.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0 || !el.innerText.trim()) return;
            handledElements.add(el);
            const box = getPixelBox(el, slideRect);
            pdf.setFont('helvetica', 'normal');
            pdf.setFontSize(12);
            pdf.setTextColor(107, 114, 128); // #6B7280
            pdf.text(el.innerText.trim(), box.x, box.y + 12);
          });

          // 14. TEXTOS RESIDUAIS / METADADOS DE CAPA
          const otherTexts = Array.from(slide.querySelectorAll('span, strong, b, em, label, small'));
          otherTexts.forEach(el => {
            if (handledElements.has(el) || el.offsetWidth <= 0 || !el.innerText.trim()) return;
            let parent = el.parentElement;
            let ancestorHandled = false;
            while (parent && parent !== slide) {
              if (handledElements.has(parent)) { ancestorHandled = true; break; }
              parent = parent.parentElement;
            }
            if (ancestorHandled) return;

            handledElements.add(el);
            const box = getPixelBox(el, slideRect);
            const isDark = el.closest('.card-elevated-green') !== null;
            pdf.setFont('helvetica', (el.tagName === 'STRONG' || el.tagName === 'B') ? 'bold' : 'normal');
            pdf.setFontSize(13);
            if (isDark) pdf.setTextColor(235, 245, 238);
            else pdf.setTextColor(75, 85, 99);
            const lines = pdf.splitTextToSize(el.innerText.trim(), box.w > 30 ? box.w : 400);
            pdf.text(lines, box.x, box.y + 12);
          });

        } catch (captureErr) {
          console.error(`Erro na composição em vetor do slide ${i + 1} para PDF:`, captureErr);
        } finally {
          slide.style.removeProperty('display');
          slide.style.removeProperty('visibility');
          slide.style.removeProperty('opacity');
          slide.style.removeProperty('transform');
          slide.style.removeProperty('position');
          slide.style.removeProperty('top');
          slide.style.removeProperty('left');
          slide.style.removeProperty('width');
          slide.style.removeProperty('height');
          slide.style.removeProperty('z-index');
          if (!prevActive) slide.classList.remove('active');
        }
      }

      currentSlide = originalSlide;
      updateSlides();

      if (btn) btn.innerText = 'Baixando PDF...';
      const cleanTitle = (document.title || 'Apresentacao-Orcamentaria')
        .replace(/[^a-zA-Z0-9À-ÿ_-]/g, '_')
        .substring(0, 35);
      pdf.save(`${cleanTitle}.pdf`);
      return pdf;

    } catch (err) {
      console.error('Falha na conversão para PDF:', err);
      alert('Não foi possível converter a apresentação para PDF. Detalhes: ' + (err && err.message ? err.message : err));
    } finally {
      if (btn) {
        btn.innerText = originalText;
        btn.disabled = false;
      }
    }
  }

  // 8. TECLADO
  document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') nextSlide();
    if (e.key === 'ArrowLeft' || e.key === 'PageUp') prevSlide();
    if (e.key === 'Home') { currentSlide = 1; updateSlides(); }
    if (e.key === 'End') { currentSlide = totalSlides; updateSlides(); }
  });

  window.addEventListener('resize', autoScale);

  // INICIALIZAÇÃO GERAL ROBUSTA
  function initDeck() {
    if (!document.body) {
      setTimeout(initDeck, 30);
      return;
    }
    sanitizeEmojis();
    ensureControls();
    initCharts();
    updateSlides();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initDeck);
  } else {
    initDeck();
  }
  window.addEventListener('load', initDeck);

  // Exporta funções para escopo global caso botões inline sejam usados
  window.nextSlide = nextSlide;
  window.prevSlide = prevSlide;
  window.toggleFullScreen = toggleFullScreen;
  window.exportPDF = exportPDF;
  window.exportPPTX = exportPPTX;
})();
